Plan:
1. Load the active sheet’s cached values and group appointment statuses by MRN in column A.
2. Apply the priority rules per MRN: only SCH → FUTURE; both NO SHOW and SCH → NS/SCHED; only NO SHOW with a date → NO ACTION NEEDED; only NO SHOW without a date → CALL PT.
3. Write the resulting plain text values into F2:F20 and save the workbook.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws = vals.active
ws = wb.active

def norm_key(v):
    if v is None:
        return None
    if isinstance(v, float) and v.is_integer():
        return int(v)
    if isinstance(v, str):
        return v.strip()
    return v

def norm_status(v):
    if v is None:
        return None
    s = str(v).strip().upper()
    if not s:
        return None
    if s in {"NO SHOW", "NO-SHOW", "NOSHOW"}:
        return "NO_SHOW"
    if s in {"SCH", "SCHED", "SCHEDULED", "SCHEDULE"}:
        return "SCH"
    return s

def has_date(v):
    if v is None:
        return False
    if isinstance(v, str) and not v.strip():
        return False
    return True

max_row = vws.max_row
groups = {}

for r in range(2, max_row + 1):
    mrn = vws.cell(row=r, column=1).value
    status = vws.cell(row=r, column=4).value
    key = norm_key(mrn)
    if key is None:
        continue
    st = norm_status(status)
    if st is not None:
        groups.setdefault(key, set()).add(st)

end_row = max(max_row, 20)
results = []

for r in range(2, end_row + 1):
    mrn = vws.cell(row=r, column=1).value
    status = vws.cell(row=r, column=4).value
    next_date = vws.cell(row=r, column=5).value

    key = norm_key(mrn)
    sts = groups.get(key, set()) if key is not None else set()

    value = None

    if sts == {"SCH"}:
        value = "FUTURE"
    elif "NO_SHOW" in sts and "SCH" in sts:
        value = "NS/SCHED"
    elif sts == {"NO_SHOW"}:
        value = "NO ACTION NEEDED" if has_date(next_date) else "CALL PT"
    else:
        row_st = norm_status(status)
        if row_st == "SCH" and "NO_SHOW" not in sts:
            value = "FUTURE"
        elif row_st == "NO_SHOW":
            value = "NO ACTION NEEDED" if has_date(next_date) else "CALL PT"

    ws.cell(row=r, column=6).value = value
    results.append((r, key, value))

wb.save(OUT)

print("Sheet:", ws.title)
print("Rows written:", len(results))
print("Sample:", results[:5])
print("Tail:", results[-5:])
```

